import java.util.*;

/**
 * Demonstrates whether weather selection depends on JVM identity-hashCode state.
 *
 * Arg = number of dummy identityHashCode computations to run BEFORE the engine is
 * built. That perturbs the thread-local hashCode PRNG, which (in the buggy
 * HashSet-based Weather) changes the iteration order of the weather set and thus
 * the weather sequence -> different fingerprint. With a deterministic Weather the
 * fingerprint is independent of this perturbation.
 *
 * Verification artifact only.
 */
public class WeatherDeterminismCheck
{
    private static final int DEPTH = 160, WIDTH = 240, STEPS = 150;

    public static void main(String[] args)
    {
        int perturb = args.length > 0 ? Integer.parseInt(args[0]) : 0;
        // Advance the identity-hashCode PRNG before WeatherType/HashSet allocation.
        long sink = 0;
        for (int i = 0; i < perturb; i++) sink += System.identityHashCode(new Object());

        Randomizer.reset();
        SimulationEngine engine = new SimulationEngine(DEPTH, WIDTH);
        engine.reset();
        long fp = 1469598103934665603L;
        StringBuilder weatherSeq = new StringBuilder();
        for (int step = 1; step <= STEPS; step++) {
            engine.step();
            fp = mix(fp, signature(engine.getField(), step));
            if (step % 12 == 0) weatherSeq.append(engine.getEnvironment().getWeather().getCurrentWeather().toString().charAt(0));
        }
        System.out.println("perturb=" + perturb + " FINGERPRINT=" + fp + " weatherChanges=" + weatherSeq
                + " (sink=" + (sink == Long.MIN_VALUE ? 1 : 0) + ")");
    }

    private static long signature(Field field, int step)
    {
        long s = 1469598103934665603L ^ step;
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object o = field.getObjectAt(row, col);
                long cell = 0;
                if (o != null) {
                    cell = o.getClass().getName().hashCode();
                    if (o instanceof Organism && ((Organism) o).isDiseased()) cell = cell * 7 + 3;
                }
                s = (s ^ cell) * 1099511628211L;
            }
        }
        return s;
    }

    private static long mix(long h, long v) { h ^= v; h *= 1099511628211L; return h; }
}

